package com.mediexplain.service;
import com.fasterxml.jackson.databind.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.http.client.JdkClientHttpRequestFactory; import org.springframework.stereotype.Service; import org.springframework.web.client.*; import java.time.Duration; import java.net.http.HttpClient; import java.util.*;
@Service public class GeminiService {
 @Value("${app.gemini.api-key}") private String apiKey; @Value("${app.gemini.model}") private String model; private final ObjectMapper mapper=new ObjectMapper();
 public String explain(String report,String question,List<String> prior){if(apiKey==null||apiKey.isBlank())throw new IllegalStateException("AI is not configured yet. Set GEMINI_API_KEY, then restart MediExplain AI.");
  try {String context=report.length()>24000?report.substring(0,24000):report;String prompt="You are MediExplain AI, an assistant helping users understand medical reports. Answer only from report context when describing findings; separate general explanation from report findings. Never diagnose or prescribe medication or treatment. Admit uncertainty or missing information. Explain terminology simply. End with: This is educational information, not a medical diagnosis. Consult a qualified healthcare professional.\n\nREPORT:\n"+context+"\n\nRECENT CHAT:\n"+String.join("\n",prior)+"\n\nQUESTION:\n"+question;
   Map<String,Object> body=Map.of("contents",List.of(Map.of("parts",List.of(Map.of("text",prompt)))));HttpClient http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(10)).build();JdkClientHttpRequestFactory factory=new JdkClientHttpRequestFactory(http);factory.setReadTimeout(Duration.ofSeconds(45));RestClient client=RestClient.builder().requestFactory(factory).build();String response=client.post().uri("https://generativelanguage.googleapis.com/v1beta/models/"+model+":generateContent").header("x-goog-api-key",apiKey).contentType(MediaType.APPLICATION_JSON).body(body).retrieve().body(String.class);
   JsonNode root=mapper.readTree(response);JsonNode answer=root.path("candidates").path(0).path("content").path("parts").path(0).path("text");if(!answer.isTextual())throw new IllegalStateException("The AI could not provide a response. Please try again shortly.");return answer.asText();
  }catch(ResourceAccessException e){throw new IllegalStateException("The AI service could not be reached. Check your connection and try again.");}catch(HttpStatusCodeException e){throw new IllegalStateException("The AI service is temporarily unavailable. Please try again shortly.");}catch(IllegalStateException e){throw e;}catch(Exception e){throw new IllegalStateException("We could not read the AI response. Please try again.");}}
}
